import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/FDroid.html","title":"FDroid","lang":"en-US","frontmatter":{},"git":{"createdTime":1730294245000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":3}]},"readingTime":{"minutes":4.2,"words":1261},"filePathRelative":"FDroid.md"}`),a={name:`FDroid.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="fdroid" tabindex="-1"><a class="header-anchor" href="#fdroid"><span>FDroid</span></a></h1><p><a href="./Android.html">Android</a>のオープンソースのアプリをホストしているStore的なもの。</p><ul><li><a href="https://f-droid.org/docs/Inclusion_How-To/" target="_blank" rel="noopener noreferrer">Inclusion How-To - F-Droid - Free and Open Source Android App Repository</a><ul><li><a href="https://gitlab.com/fdroid/fdroiddata/blob/master/CONTRIBUTING.md#metadata-preparation-with-fdroidserver" target="_blank" rel="noopener noreferrer">CONTRIBUTING.md · master · F-Droid / Data · GitLab</a></li></ul></li><li><a href="https://qiita.com/wa2c/items/4a4b5096eed4ee3a0dee" target="_blank" rel="noopener noreferrer">F-Droidにアプリを登録してみた #Android - Qiita</a> ちょっと古めなので基本的な流れを知るくらいで、実際の作業は公式ドキュメントに沿ったほうが良さそう。</li></ul><p><a href="./バイク整備記録.html">バイク整備記録</a>をF-Droidに登録してみたいな。</p><h2 id="てきすとtlを試しに登録してみる-2025-10-16-木" tabindex="-1"><a class="header-anchor" href="#てきすとtlを試しに登録してみる-2025-10-16-木"><span>てきすとTLを試しに登録してみる 2025-10-16 (木)</span></a></h2><p>とりあえず一番単純なアプリ、<a href="./てきすとTL.html">てきすとTL</a>を試しに登録してみる。 まずはライブラリとかを一通りアップデートする事から。</p><p>そのあとは以下を順番に見ていく。</p><p><a href="https://f-droid.org/docs/Inclusion_How-To/" target="_blank" rel="noopener noreferrer">Inclusion How-To - F-Droid - Free and Open Source Android App Repository</a></p><p>なんか読めというドキュメントが大量にあってそりゃ無理よ、って感じなので適当に飛ばして先に進む。 GitLabのアカウントが必要らしいが、GitHubでログイン、でそれっぽいアカウントが出来たっぽいのでそれで進む。</p><p>次にF-Droid serverが必要、とあるが、インストールへのリンクがないので適当にググって以下へ。</p><p><a href="https://f-droid.org/docs/Installing_the_Server_and_Repo_Tools/#homebrew" target="_blank" rel="noopener noreferrer">Installing the Server and Repo Tools - F-Droid - Free and Open Source Android App Repository</a></p><p>brew installで入るっぽい。</p><p>で、fdroiddataというレポジトリをforkしてcloneする、とのこと。結構時間がかかるので他の事をして待つ。</p><p>次にfdroiddataのディレクトリにcdして、以下を実行。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ fdroid import --url https://github.com/karino2/TextTL/ --subdir app</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>で出来たファイルを見たが問題は無さそう。</p><p>という事で次はビルドらしい。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ fdroid rewritemeta io.github.karino2.texttl</span>
<span class="line">$ fdroid checkupdates io.github.karino2.texttl</span>
<span class="line">2025-10-16 21:53:02,359 ERROR: ビルドのメタデータのgitリポジトリにcommitされていない変更があります！</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>おや、エラーと言われた。そしてエラーメッセージが日本語なのでググってもひっっからない…</p><p>エラーメッセージから見ると、どうもさっきimportで作ったymlをコミットしてないといけないっぽい。 手順には書いてないがコミットしてみよう。（ブランチは切ってある）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ git add metadata/io.github.karino2.texttl.yml</span>
<span class="line">$ git commit -m &quot;New app: TextTL&quot;</span>
<span class="line">$ fdroid checkupdates io.github.karino2.texttl</span>
<span class="line">2025-10-16 22:09:30,006 INFO: io.github.karino2.texttlを処理</span>
<span class="line">2025-10-16 22:09:42,412 ERROR: 環境変数{env: serverwebroot}が未設定です！</span>
<span class="line">2025-10-16 22:09:42,412 ERROR: serverwebroot: has blank value!</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>えー、知らないよ…</p><p>Geminiに聞いたら、ダミーを設定しろ、と言ってきた。ほんとかな… 少しググったがわからなかったのでgeminiに従う。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$  export serverwebroot=&quot;/tmp/fdroid/repo&quot;</span>
<span class="line">$ fdroid checkupdates io.github.karino2.texttl</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>お、うまくいった。次はlintをしろと言っているな。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line"> % fdroid lint io.github.karino2.texttl</span>
<span class="line">io.github.karino2.texttl: カテゴリーが設定されていません</span>
<span class="line">io.github.karino2.texttl: 予期されていないライセンスタグ「Unknown」です！https://spdx.org/license-list から、FSFまたはOSIにより認証されたタグのみを使用してください</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>おや、レポジトリにLICENSEファイルあるはずだが。Metadataのリファレンスは読んでおけというドキュメントの中にあったな。以下か。</p><p><a href="https://f-droid.org/docs/Build_Metadata_Reference/" target="_blank" rel="noopener noreferrer">Build Metadata Reference - F-Droid - Free and Open Source Android App Repository</a></p><p>他人のymlを参考に手直していおく。 lintも通った。良さそう。</p><p>次はビルド。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">% fdroid build -v -l  io.github.karino2.texttl</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>なんかすぐ終わってしまったが、バイナリは出来てなさそうだな。</p><p>どうも.ymlのBuildセクションをテンプレートを参考に手直ししろ、という事らしい。 disableの行を消せばだいたいいいかな。</p><p>で、実行。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">2025-10-16 23:21:59,108 ERROR: Could not build app io.github.karino2.texttl: OSError while trying to execute /usr/local/Cellar/fdroidserver/2.4.2/libexec/lib/python3.14/site-packages/gradlew-fdroid clean: [Errno 2] No such file or directory: &#39;/usr/local/Cellar/fdroidserver/2.4.2/libexec/lib/python3.14/site-packages/gradlew-fdroid&#39;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>えー、知らないよ… とりあえずuninstallしてinstallしなおすか。結果変わらず。うーん。</p><p>ググってみたら以下がひっかかる。</p><p><a href="https://gitlab.com/fdroid/gradlew-fdroid" target="_blank" rel="noopener noreferrer">F-Droid / gradlew-fdroid · GitLab</a></p><p>とりあえずこのシェルスクリプトを該当フォルダに置いて見るか。</p><p>お、なんかビルドされたっぽい。 ただビルドは成功したっぽいがそのあとのフェースでエラーになってるな。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">2025-10-16 23:36:59,824 INFO: Scanning source for common problems...</span>
<span class="line">2025-10-16 23:36:59,831 DEBUG: scanner is configured to use signature data from: &#39;suss&#39;</span>
<span class="line">2025-10-16 23:36:59,832 DEBUG: &#39;https://fdroid.gitlab.io/fdroid-suss/suss.json&#39;をダウンロードしています</span>
<span class="line">2025-10-16 23:37:01,062 DEBUG: write &#39;suss.json&#39; to cache</span>
<span class="line">2025-10-16 23:37:01,064 DEBUG: 次のsuss.jsonキャッシュの更新まで23:59:59.995536</span>
<span class="line">2025-10-16 23:37:01,110 ERROR: Found usual suspect &#39;com.android.application.*8.13.0&#39; at build.gradle</span>
<span class="line">2025-10-16 23:37:01,122 INFO: Removing gradle-wrapper.jar at gradle/wrapper/gradle-wrapper.jar</span>
<span class="line">2025-10-16 23:37:01,125 ERROR: Could not build app io.github.karino2.texttl: スキャン時に1個のエラーが発生したためビルドできません</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>なんだろう？issueを検索すると、二ヶ月前に直した形跡があるな。</p><p><a href="https://gitlab.com/fdroid/fdroiddata/-/issues/3601" target="_blank" rel="noopener noreferrer">Build fails due to com.android.application.*8.12.0 flagged by scanner [ com.maazm7d.quickse ] (#3601) · Issue · fdroid/fdroiddata</a></p><p>そして今のバージョンは6月にリリースされてるっぽいな。うーん、まだ入ってないということか？ いや、リンク先を見たらまだopenだな、これ。</p><p><a href="https://gitlab.com/fdroid/admin/-/issues/593" target="_blank" rel="noopener noreferrer">aapt2 fails to run on the buildserver - AGP 8.12.0-alpha07 is latest compatible (#593) · Issue · fdroid/admin</a></p><p>うーん、今日のところはこのくらいにしておいてやるか。</p><h3 id="dockerを試してみる-2025-10-18-土" tabindex="-1"><a class="header-anchor" href="#dockerを試してみる-2025-10-18-土"><span>Dockerを試してみる 2025-10-18 (土)</span></a></h3><p>少し時間をあけて冷静に考えた所、Mac版は面倒そうなのでDocker版を使おう、と思い立つ。</p><p>公式リンクから辿って以下。</p><p><a href="https://gitlab.com/fdroid/docker-executable-fdroidserver" target="_blank" rel="noopener noreferrer">F-Droid / docker-executable-fdroidserver · GitLab</a></p><p>Build your appのセクションを見ると、以下を実行すればいいか？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">docker run --rm -v $ANDROID_HOME:/opt/android-sdk -v $(pwd):/repo -e ANDROID_HOME:/opt/android-sdk registry.gitlab.com/fdroid/docker-executable-fdroidserver:master build io.github.karino2.texttl:1 -v</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>無事動いてそうだが、同じエラーになった。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">2025-10-18 02:06:06,319 ERROR: Found usual suspect &#39;com.android.application.*8.13.0&#39; at build.gradle</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>これは駄目そうだがfdroidserverのセットアップ周りの問題がない分docker imageの方が良さそうだな。</p><h3 id="usual-suspectのエラーを真面目に解決" tabindex="-1"><a class="header-anchor" href="#usual-suspectのエラーを真面目に解決"><span>usual suspectのエラーを真面目に解決</span></a></h3><p>ちょっと真面目にこのエラーを調べてみた。以下のissueがそれなんだが、長くてわかりにくい。</p><p><a href="https://gitlab.com/fdroid/admin/-/issues/593" target="_blank" rel="noopener noreferrer">aapt2 fails to run on the buildserver - AGP 8.12.0-alpha07 is latest compatible (#593) · Issue · fdroid/admin</a></p><p>どうも特定のgradleとAGPのバージョンの組み合わせはエラーになっていて、一時的に古いAGPを使え、という事っぽい。 そしてそのためにはとりあえずsedを使え、と言っている。</p><p>grepで他の人がどうやってるかを見る。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">cd metadata</span>
<span class="line">grep &quot;8\\.13&quot; *.yml</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>どうも関連する所を見ると以下っぽいか？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">prebuild: sed -i -e &#39;s/8.13.0/8.11.1/&#39; ../build.gradle</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>相対パスがどこをさしているのかとか良くわからないが、とりあえずymlにコピペしてみるか。</p><p>おぉ、ビルド通った。これで良さそう。</p><h3 id="dockerで手順をちゃんと進めてみる" tabindex="-1"><a class="header-anchor" href="#dockerで手順をちゃんと進めてみる"><span>dockerで手順をちゃんと進めてみる</span></a></h3><p>ビルドが出来たので最初からやっていこう。 以下のドキュメントのBuilding itをもう一度進めてみる。</p><p><a href="https://gitlab.com/fdroid/fdroiddata/blob/master/CONTRIBUTING.md" target="_blank" rel="noopener noreferrer">CONTRIBUTING.md · master · F-Droid / Data · GitLab</a></p><p>とりあえずlintをもう一回やってみたらいいかな。dockerでのlintは以下か？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">docker run --rm -v $ANDROID_HOME:/opt/android-sdk -v $(pwd):/repo -e ANDROID_HOME:/opt/android-sdk registry.gitlab.com/fdroid/docker-executable-fdroidserver:master lint io.github.karino2.texttl -v</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>問題無さそうね。＞問題あったっぽいがなんか表示されてなかった（なんで？）</p><p>次はこれを自分のforkにpushして、Common steps for both methodsのセクションを進める感じか。 ブランチをpushしてみよう。</p><p>そしてgitlabのCI/CDセクションを見る、か。左側のペイン（隠れているが右上のボタンで開けた）でBuildの下のpipelinesを見る。</p><p>おや、failしている。git labでaccountをverifyしろ、とか言われているな。したような気がするが…</p><p>Verify My Accountというボタンがあるので押して見ると、電話番号を入力させられてSMSが来た。これはやってないな。</p><p>verifyしたので再実行しようとしたがやり方が良くわからんな。New Pipelineというのを選んでinputを入れろというのを何もせずにNewを選んだら、なんかいろいろ走り出した。</p><p>無事パスしたが、MR作ろうとしたらこのコミットのCIのfailアイコンが目立って感じ悪いので、メッセージだけ少し修正してforce pushでやりなおし。</p><h3 id="mrを作っての印象" tabindex="-1"><a class="header-anchor" href="#mrを作っての印象"><span>MRを作っての印象</span></a></h3><ul><li>リモートのmasterをforkのmasterにsyncし忘れてpullを試していた</li><li>MRのCIでlintが何故か失敗した（なぜforkで成功しているのかは良くわからない。prebuildの位置を変えろと言ってきたので直す）</li><li>fastlaneでのビルドは必須ではないがMRのテンプレートでstrongly recommendedとされていた（次は試したい）</li></ul><h3 id="fastlane対応-2025-10-19-日" tabindex="-1"><a class="header-anchor" href="#fastlane対応-2025-10-19-日"><span>fastlane対応 2025-10-19 (日)</span></a></h3><p>MRのフィードバックでfastlaneを追加してね、とだけ帰ってきた。必須では無いんじゃなの？という気もするが、 やりとりするよりもfastlaneを加える方が早そう。</p><p>実質必須だと思っておく方が良さそうだ。</p><p>まずbrew installでfastlaneを入れる。（追記：この辺は不要だった）</p><p><a href="https://docs.fastlane.tools/" target="_blank" rel="noopener noreferrer">fastlane docs</a></p><p>で、次はfastlane initをすればいいっぽいか。</p><p><a href="https://docs.fastlane.tools/getting-started/android/setup/" target="_blank" rel="noopener noreferrer">Setup - fastlane docs</a></p><p>なぜかパッケージ名が全然違うものが出てきたので自分のものを入れる。</p><p>Google Playにアップロードするならauth系の情報が必要だ、と言われるが、それはやらないのでスルー。</p><p>で、終わってみたが、生成されたタスクが以下の３つ。</p><ul><li>テストを走らせる</li><li>Crashlytics Betaにsubmit</li><li>Google Playにsubmit</li></ul><p>どれも必要そうには見えない。fastlaneで何をしろ、というのだろう？</p><p>すでにサブミットされているアプリを見てみると、以下のようになっている。</p><p><a href="https://github.com/johannesjo/super-productivity/tree/master/fastlane" target="_blank" rel="noopener noreferrer">super-productivity/fastlane at master · johannesjo/super-productivity</a></p><p>FastfileもAppfileも無いな。</p><p>少しググってみて、以下の２つにたどり着く</p><ul><li><a href="https://gitlab.com/-/snippets/1895688" target="_blank" rel="noopener noreferrer">Fastlane file structure ($1895688) · Snippets · GitLab</a></li><li><a href="https://gitlab.com/IzzyOnDroid/repo/-/wikis/Fastlane" target="_blank" rel="noopener noreferrer">Fastlane · Wiki · IzzyOnDroid / repo · GitLab</a></li></ul><p>後者の記述は詳しいが、ようするにmetadataだけで良さそうに読める。 とりあえずfastfileとappfileを削除してmetadataを作ってみよう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">% cd fastlane</span>
<span class="line">% mkdir -p metadata/android/en-US</span>
<span class="line">% cd metadata/android/en-US</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>で、それっぽいのを一通り埋めたが、このあとどうしたらいいんだ？</p><p>docker imageでvalidatio出来そうか。以下を実行。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">% docker run --rm --workdir /app --mount type=bind,source=&quot;$(pwd)&quot;,target=/app \\</span>
<span class="line">   ashutoshgngwr/validate-fastlane-supply-metadata:v1 -fastlane-path ./fastlane</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>いくつかすぐに分かるミスが出てきたのでそれを直し、最後に以下が残る。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">fastlane/metadata/android/en-US/images/phoneScreenshots/1.png: &#39;max:min&#39; edge radio should be at most 2.0: got=2.22</span>
<span class="line">fastlane/metadata/android/en-US/images/phoneScreenshots/2.png: &#39;max:min&#39; edge radio should be at most 2.0: got=2.22</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>なんで俺のスマホのスクショじゃ駄目なん？とりあえず幅を広げて2:1くらいにして無事パス。</p><h3 id="fastlane関連で必要な事" tabindex="-1"><a class="header-anchor" href="#fastlane関連で必要な事"><span>fastlane関連で必要な事</span></a></h3><p>ようするにF-Droidで公開されるページのデータだけが必要っぽい。 という事でfastlaneのインストールは不要な気がする。</p><p>単にfastlane/metadata下を他の人を参考に作り、dockerのlsupply-metadataという奴で確認すれば十分っぽい。</p><h3 id="texttlがマージされる-2025-11-04-火" tabindex="-1"><a class="header-anchor" href="#texttlがマージされる-2025-11-04-火"><span>TextTLがマージされる 2025-11-04 (火)</span></a></h3><p>先ほど無事マージされた。FDroidのサイトにはまだ無さそうだが。</p><p><a href="https://gitlab.com/fdroid/fdroiddata/-/merge_requests/28307" target="_blank" rel="noopener noreferrer">New app: TextTL (!28307) · マージリクエスト · F-Droid / Data · GitLab</a></p><p>全て不備を直してreview-requestedのラベルが付いたのが10月19日で、2週間くらいでマージされた。 作業の多くは結局FDroidのページに表示される情報を揃えることなので、やってみるとリリース作業はそんなに大変ではないな。</p><p>今後はFDroidに置いていこう。</p><h3 id="fdroidのサイトの検索に引っ掛かるようになる-2025-11-07-金" tabindex="-1"><a class="header-anchor" href="#fdroidのサイトの検索に引っ掛かるようになる-2025-11-07-金"><span>FDroidのサイトの検索に引っ掛かるようになる 2025-11-07 (金)</span></a></h3><p><a href="https://f-droid.org/ja/packages/io.github.karino2.texttl/" target="_blank" rel="noopener noreferrer">TextTL - F-Droid - Free and Open Source Android App Repository</a></p><p>なかなか出てこないなと思っていたが、実際はマージされてから3日くらいか。まぁまぁすぐか。</p>`,115)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};